package AutonomousDroneBehavior {

    // OWNER: FlightController
    action def incorporateWaypoints { }

    // OWNER: FlightController
    state def WaypointManagementBehavior {
        state WpmIdle;
        state WpmUpdatingWaypoints {
            entry action onUpdate : incorporateWaypoints;
        }
        entry; then WpmIdle;
        transition startUpdate
            first WpmIdle
            accept ValidWaypointModificationCommand
            then WpmUpdatingWaypoints;
    }

    // OWNER: CommunicationSystem
    action def transmitHealthReport { }

    // OWNER: CommunicationSystem
    state def HealthReportingBehavior {
        state HrbIdle;
        state HrbReportingHealth {
            entry action onReport : transmitHealthReport;
        }
        entry; then HrbIdle;
        transition startReport
            first HrbIdle
            accept AutomatedLandingCompleted
            then HrbReportingHealth;
    }

    // OWNER: PropulsionSystem
    action def maintainControlledFlight { }

    // OWNER: PropulsionSystem
    state def PropulsionControlBehavior {
        state PcbNominal;
        state PcbSingleFailureRecovery {
            do action onRecovery : maintainControlledFlight;
        }
        entry; then PcbNominal;
        transition handleFailure
            first PcbNominal
            accept SingleUnitFailure
            then PcbSingleFailureRecovery;
    }

    // OWNER: FlightController
    action def armSystem { }

    // OWNER: FlightController
    state def PowerOnSelfTestBehavior {
        state PostPowerOn;
        state PostArmed {
            entry action onArm : armSystem;
        }
        entry; then PostPowerOn;
        transition armSystemTransition
            first PostPowerOn
            accept ArmCommand
            if not sensorSelfTestFailed
            then PostArmed;
    }

    // OWNER: PayloadMechanism
    action def lockPayload { }

    // OWNER: PayloadMechanism
    action def releasePayload { }

    // OWNER: PayloadMechanism
    state def PowerOnDeliveryAbortBehavior {
        state PodaPowerOn;
        state PodaMechanicallyLocked {
            entry action onLock : lockPayload;
        }
        state PodaReleased {
            entry action onRelease : releasePayload;
        }
        entry; then PodaPowerOn;
        transition initializeLock
            first PodaPowerOn
            accept PowerOnEvent
            then PodaMechanicallyLocked;
        transition release
            first PodaMechanicallyLocked
            accept ReleaseCommand
            if not deliveryAbortConditionActive
            then PodaReleased;
    }

    // OWNER: CommunicationSystem
    action def broadcastRemoteId { }

    // OWNER: CommunicationSystem
    state def SpatialPositioningRemoteIdBehavior {
        state SprbIdle;
        state SprbBroadcasting {
            do action onBroadcast : broadcastRemoteId;
        }
        entry; then SprbIdle;
        transition startBroadcast
            first SprbIdle
            accept SystemArmed
            then SprbBroadcasting;
    }

    // OWNER: FlightController
    action def maintainCruise { }

    // OWNER: FlightController
    state def CruiseFlightBehavior {
        state CfbIdle;
        state CfbSteadyCruiseFlight {
            do action onCruise : maintainCruise;
            assert constraint rollPitchAttitudeDeviationsConstraint {
                currentRollPitchAttitudeDeviations <= maxRollPitchAttitudeDeviations
            }
        }
        entry; then CfbIdle;
        transition enterCruise
            first CfbIdle
            accept TakeoffComplete
            then CfbSteadyCruiseFlight;
    }

    // OWNER: FlightController
    action def maintainMaxPayloadCruise { }

    // OWNER: FlightController
    state def PayloadCruiseBehavior {
        state PlcbIdle;
        state PlcbMaxPayloadCruise {
            do action onMaxPayload : maintainMaxPayloadCruise;
            assert constraint flightDurationConstraint {
                currentFlight >= minFlight
            }
        }
        entry; then PlcbIdle;
        transition detectMaxPayload
            first PlcbIdle
            accept MaxPayloadDetected
            then PlcbMaxPayloadCruise;
    }

    // OWNER: FlightController
    action def compensateHeadwind { }

    // OWNER: FlightController
    state def HeadwindFlightBehavior {
        state HfbIdle;
        state HfbHeadwindOperation {
            do action onHeadwind : compensateHeadwind;
            assert constraint forwardGroundSpeedConstraint {
                currentForwardGroundSpeed >= minForwardGroundSpeed
            }
        }
        entry; then HfbIdle;
        transition detectHeadwind
            first HfbIdle
            accept HeadwindDetected
            then HfbHeadwindOperation;
    }

    // OWNER: FlightController
    action def navigateWaypoints { }

    // OWNER: FlightController
    state def NavigationBehavior {
        state NavIdle;
        state NavNavigatingWaypoints {
            do action onNavigate : navigateWaypoints;
        }
        entry; then NavIdle;
        transition startNavigation
            first NavIdle
            accept WaypointReceived
            then NavNavigatingWaypoints;
    }

    // OWNER: FlightController
    action def navigateAvoidance { }

    // OWNER: FlightController
    state def AvoidanceBehavior {
        state AvdIdle;
        state AvdAvoidingObstacle {
            do action onAvoidance : navigateAvoidance;
        }
        entry; then AvdIdle;
        transition startAvoidance
            first AvdIdle
            accept ThreatDetected
            then AvdAvoidingObstacle;
    }

    // OWNER: SafetyMonitor
    action def CMD_RTB { }

    // OWNER: SafetyMonitor
    action def CMD_LAND { }

    // OWNER: SafetyMonitor
    action def CMD_PARACHUTE { }

    // OWNER: SafetyMonitor
    action def initiateBatteryRtb {
        send CMD_RTB() to rtbCmd;
    }

    // OWNER: SafetyMonitor
    action def initiateEmergencyLand {
        send CMD_LAND() to landingCmd;
    }

    // OWNER: SafetyMonitor
    action def deployParachute {
        send CMD_PARACHUTE() to parachuteCmd;
    }

    // OWNER: SafetyMonitor
    state def BatteryRtbMonitor {
        state RtbNominal;
        state RtbDetected;
        entry; then RtbNominal;
        transition detectRtb
            first RtbNominal
            if batterySoc <= 25.0
            then RtbDetected;
    }

    // OWNER: SafetyMonitor
    state def BatteryLandMonitor {
        state LandNominal;
        state LandDetected;
        entry; then LandNominal;
        transition detectLand
            first LandNominal
            if batterySoc < 15.0
            then LandDetected;
    }

    // OWNER: SafetyMonitor
    state def CommLossMonitor {
        state CommNominal;
        state CommDetected;
        entry; then CommNominal;
        transition detectCommLoss
            first CommNominal
            if commLossTime > 10.0
            then CommDetected;
    }

    // OWNER: SafetyMonitor
    state def PropulsionFailureMonitor {
        state PropNominal;
        state PropDetected;
        entry; then PropNominal;
        transition detectPropFailure
            first PropNominal
            if propulsionCriticalFailure
            then PropDetected;
    }

    // OWNER: SafetyMonitor
    state def SafetyArbiter {
        state ArbNominal;

        state ArbParachuteMode {
            entry action onParachute : deployParachute;
        }

        state ArbLandMode {
            entry action onLand : initiateEmergencyLand;
        }

        state ArbRtbMode {
            entry action onRtb : initiateBatteryRtb;
        }

        entry; then ArbNominal;

        transition toParachute
            first ArbNominal
            if propulsionCriticalFailure
            then ArbParachuteMode;

        transition toLandBattery
            first ArbNominal
            if batterySoc < 15.0
            and not propulsionCriticalFailure
            then ArbLandMode;

        transition toLandComm
            first ArbNominal
            if commLossTime > 10.0
            and not propulsionCriticalFailure
            then ArbLandMode;

        transition toRtb
            first ArbNominal
            if batterySoc <= 25.0
            and batterySoc >= 15.0
            and commLossTime <= 10.0
            and not propulsionCriticalFailure
            then ArbRtbMode;
    }

    // OWNER: FlightController
    assert constraint waypointModificationLatencyConstraint {
        waypointModificationLatency <= 1.0
    }

    // OWNER: FlightController
    assert constraint currentSeparationConstraint {
        currentAirframeObstacleSeparation >= minAirframeObstacleSeparation
    }

    // OWNER: FlightController
    assert constraint hoverThrottleMarginConstraint {
        currentHoverThrottleMargin >= minHoverThrottleMargin
    }

    // OWNER: FlightController
    assert constraint cruiseAirspeedConstraint {
        currentCruiseAirspeed >= minCruiseAirspeed
    }

    // OWNER: FlightController
    assert constraint operationalRangeConstraint {
        currentOperationalRange >= minOperationalRange
    }

    // OWNER: FlightController
    assert constraint flightAltitudeConstraint {
        currentFlightAltitude <= maxFlightAltitude
    }

    // OWNER: FlightController
    assert constraint takeOffMassPayloadBatteryConstraint {
        currentTakeOffMassPayloadBattery <= maxTakeOffMassPayloadBattery
    }

    // OWNER: CommunicationSystem
    assert constraint healthReportDelayConstraint {
        healthReportDelay <= 5.0
    }

    // OWNER: PayloadMechanism
    assert constraint releaseActuationTimeConstraint {
        releaseActuationTime <= 2.0
    }
}
